//! Geometry generation: spiral point sequence used as earcut input.

use std::f64::consts::PI;

/// Build the reference spiral of `2 * n` points.
///
/// For `i` in `0..2n`:
/// - `t = i as f64 / (2n) as f64`
/// - `radius = t`
/// - `angle = (4.0 * PI) * t`
/// - point = `(radius * cos(angle), radius * sin(angle))`
///
/// Negative or zero `n` yields an empty vector (no points).
pub fn spiral(n: i32) -> Vec<[f64; 2]> {
    if n <= 0 {
        return Vec::new();
    }
    let count = n * 2;
    let denom = count as f64;
    let mut points = Vec::with_capacity(count as usize);
    for i in 0..count {
        let t = i as f64 / denom;
        let radius = t;
        let angle = (4.0 * PI) * t;
        points.push([radius * angle.cos(), radius * angle.sin()]);
    }
    points
}

