args.content:
//! Command-line parsing matching the reference C++ behavior: the first
//! user-supplied argument is parsed like glibc `atoi`, defaulting to 7.

/// Parse `n` from the first command-line argument.
///
/// Behavior matches glibc `atoi` on the first user argument:
/// - missing argument => 7
/// - leading C whitespace skipped (space, \t, \n, \v, \f, \r)
/// - optional '+'/'-' sign
/// - leading decimal digits consumed
/// - no digits => 0
/// - digit accumulation saturates to i64::MAX / i64::MIN (strtol-style)
/// - result cast/wrapped to i32 via `as i32`
///
/// Extra arguments are ignored.
pub fn parse_n() -> i32 {
    let arg = match std::env::args().nth(1) {
        Some(a) => a,
        None => return 7,
    };
    atoi(&arg)
}

fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;

    // glibc isspace(): space, \t, \n, \v, \f, \r
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    // Accumulate like strtol with long saturation (LONG_MAX / LONG_MIN).
    let mut value: i64 = 0;
    let mut overflowed = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        if !overflowed {
            let digit = (bytes[i] - b'0') as i64;
            match value
                .checked_mul(10)
                .and_then(|v| v.checked_add(digit))
            {
                Some(v) => value = v,
                None => overflowed = true,
            }
        }
        i += 1;
    }

    if overflowed {
        value = i64::MAX;
    }

    let result: i64 = if negative {
        if overflowed {
            // strtol returns LONG_MIN on negative overflow.
            i64::MIN
        } else {
            -value
        }
    } else {
        value
    };

    result as i32
}

