//! Deterministic Mapbox-earcut-style ear clipping triangulation (std-only port).
//!
//! Single outer ring, no holes. Nodes live in a `Vec` and are referenced by
//! `u32` indices (no Rc/RefCell). Follows earcut.js / earcut.hpp semantics:
//! z-order hashing kicks in when the flattened coordinate count exceeds 160.

use std::ops::{Index, IndexMut};

const NULL: u32 = u32::MAX;

struct Node {
    i: u32, // original vertex index
    x: f64,
    y: f64,
    prev: u32,
    next: u32,
    z: i32, // 15-bit Morton code (0 until computed)
    prev_z: u32,
    next_z: u32,
    steiner: bool,
}

// node arena indexed by u32 node ids
struct Pool(Vec<Node>);

impl Index<u32> for Pool {
    type Output = Node;
    fn index(&self, id: u32) -> &Node {
        &self.0[id as usize]
    }
}

impl IndexMut<u32> for Pool {
    fn index_mut(&mut self, id: u32) -> &mut Node {
        &mut self.0[id as usize]
    }
}

pub fn earcut(points: &[[f64; 2]]) -> Vec<u32> {
    let m = points.len();
    let mut triangles: Vec<u32> = Vec::new();
    if m == 0 {
        return triangles;
    }

    // Enable z-order hashing when flattened coordinate count > 160 (m > 80).
    let (hashing, min_x, min_y, inv_size) = if m * 2 > 160 {
        let mut min_x = points[0][0];
        let mut max_x = points[0][0];
        let mut min_y = points[0][1];
        let mut max_y = points[0][1];
        for p in &points[1..] {
            min_x = min_x.min(p[0]);
            max_x = max_x.max(p[0]);
            min_y = min_y.min(p[1]);
            max_y = max_y.max(p[1]);
        }
        let mut inv = (max_x - min_x).max(max_y - min_y);
        inv = if inv != 0.0 { 32767.0 / inv } else { 0.0 };
        (true, min_x, min_y, inv)
    } else {
        (false, 0.0, 0.0, 0.0)
    };

    let mut e = Earcut {
        nodes: Pool(Vec::with_capacity(m)),
    };
    if let Some(outer) = e.linked_list(points, true) {
        if e.nodes[outer].prev == e.nodes[outer].next {
            return triangles;
        }
        e.earcut_linked(outer, &mut triangles, min_x, min_y, inv_size, 0, hashing);
    }
    triangles
}

struct Earcut {
    nodes: Pool,
}

impl Earcut {
    // signed area of the ring: sum((x[j]-x[i])*(y[i]+y[j])), j = previous index
    fn signed_area(points: &[[f64; 2]]) -> f64 {
        let m = points.len();
        let mut sum = 0.0f64;
        let mut j = m - 1;
        for i in 0..m {
            sum += (points[j][0] - points[i][0]) * (points[i][1] + points[j][1]);
            j = i;
        }
        sum
    }

    // create a circular doubly linked list from the ring in source order when
    // clockwise == (signed area > 0), otherwise in reverse order
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> Option<u32> {
        let m = points.len();
        if m == 0 {
            return None;
        }
        let mut last: Option<u32> = None;
        if clockwise == (Self::signed_area(points) > 0.0) {
            for i in 0..m {
                last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
            }
        } else {
            for i in (0..m).rev() {
                last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
            }
        }
        let mut last = last?;
        if self.nodes_eq(last, self.nodes[last].next) {
            self.remove_node(last);
            last = self.nodes[last].next;
        }
        Some(last)
    }

    // main loop: slice off ears one by one
    #[allow(clippy::too_many_arguments)]
    fn earcut_linked(
        &mut self,
        ear: u32,
        triangles: &mut Vec<u32>,
        min_x: f64,
        min_y: f64,
        inv_size: f64,
        pass: u8,
        hashing: bool,
    ) {
        // interlink polygon nodes in z-order on the first (outer) pass
        if pass == 0 && inv_size != 0.0 {
            self.index_curve(ear, min_x, min_y, inv_size);
        }

        let mut ear = ear;
        let mut stop = ear;
        let mut pass = pass;

        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if hashing {
                self.is_ear_hashed(ear, min_x, min_y, inv_size)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                triangles.push(self.nodes[prev].i);
                triangles.push(self.nodes[ear].i);
                triangles.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;
                continue;
            }

            ear = next;

            // looped through the whole remaining polygon without finding an ear
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    ear = self.filter_points(ear, None);
                    pass = 1;
                } else if pass == 1 {
                    // try curing all small self-intersections locally
                    let filtered = self.filter_points(ear, None);
                    ear = self.cure_local_intersections(filtered, triangles);
                    pass = 2;
                } else if pass == 2 {
                    // last resort: split the remaining polygon in two
                    self.split_earcut(ear, triangles, min_x, min_y, inv_size, hashing);
                }
                break;
            }
        }
    }

    // check whether a triangle (prev, ear, next) is an ear; O(n) blocker scan
    fn is_ear(&self, ear: u32) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let x0 = ax.min(bx).min(cx);
        let y0 = ay.min(by).min(cy);
        let x1 = ax.max(bx).max(cx);
        let y1 = ay.max(by).max(cy);

        let mut p = self.nodes[c].next;
        while p != a {
            if self.nodes[p].x >= x0
                && self.nodes[p].x <= x1
                && self.nodes[p].y >= y0
                && self.nodes[p].y <= y1
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }
        true
    }

    // z-order hashed variant of the ear check
    fn is_ear_hashed(&self, ear: u32, min_x: f64, min_y: f64, inv_size: f64) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false;
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let x0 = ax.min(bx).min(cx);
        let y0 = ay.min(by).min(cy);
        let x1 = ax.max(bx).max(cx);
        let y1 = ay.max(by).max(cy);

        let min_z = z_order(x0, y0, min_x, min_y, inv_size);
        let max_z = z_order(x1, y1, min_x, min_y, inv_size);

        let mut p = self.nodes[ear].prev_z;
        let mut n = self.nodes[ear].next_z;

        // look for points inside the triangle in both directions
        while p != NULL && self.nodes[p].z >= min_z && n != NULL && self.nodes[n].z <= max_z {
            if self.nodes[p].x >= x0
                && self.nodes[p].x <= x1
                && self.nodes[p].y >= y0
                && self.nodes[p].y <= y1
                && p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;

            if self.nodes[n].x >= x0
                && self.nodes[n].x <= x1
                && self.nodes[n].y >= y0
                && self.nodes[n].y <= y1
                && n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[n].x, self.nodes[n].y)
                && self.area(self.nodes[n].prev, n, self.nodes[n].next) >= 0.0
            {
                return false;
            }
            n = self.nodes[n].next_z;
        }

        // look for remaining points in decreasing z-order
        while p != NULL && self.nodes[p].z >= min_z {
            if self.nodes[p].x >= x0
                && self.nodes[p].x <= x1
                && self.nodes[p].y >= y0
                && self.nodes[p].y <= y1
                && p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        // look for remaining points in increasing z-order
        while n != NULL && self.nodes[n].z <= max_z {
            if self.nodes[n].x >= x0
                && self.nodes[n].x <= x1
                && self.nodes[n].y >= y0
                && self.nodes[n].y <= y1
                && n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[n].x, self.nodes[n].y)
                && self.area(self.nodes[n].prev, n, self.nodes[n].next) >= 0.0
            {
                return false;
            }
            n = self.nodes[n].next_z;
        }
        true
    }

    // eliminate colinear or duplicate points; returns the new end node
    fn filter_points(&mut self, start: u32, end: Option<u32>) -> u32 {
        let mut end = end.unwrap_or(start);
        let mut p = start;
        loop {
            let mut again = false;

            let pn = self.nodes[p].next;
            let pp = self.nodes[p].prev;
            if !self.nodes[p].steiner && (self.nodes_eq(p, pn) || self.area(pp, p, pn) == 0.0) {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }
        end
    }

    // walk the ring and try to cure small local self-intersections
    fn cure_local_intersections(&mut self, start: u32, triangles: &mut Vec<u32>) -> u32 {
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            if !self.nodes_eq(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                triangles.push(self.nodes[a].i);
                triangles.push(self.nodes[p].i);
                triangles.push(self.nodes[b].i);

                self.remove_node(p);
                let pn = self.nodes[p].next;
                self.remove_node(pn);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        self.filter_points(p, None)
    }

    // try to find a valid diagonal and split the remaining polygon in two
    fn split_earcut(
        &mut self,
        start: u32,
        triangles: &mut Vec<u32>,
        min_x: f64,
        min_y: f64,
        inv_size: f64,
        hashing: bool,
    ) {
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    let a2 = self.filter_points(a, Some(a_next));
                    let c_next = self.nodes[c].next;
                    let c2 = self.filter_points(c, Some(c_next));

                    // run earcut on each half
                    self.earcut_linked(a2, triangles, min_x, min_y, inv_size, 0, hashing);
                    self.earcut_linked(c2, triangles, min_x, min_y, inv_size, 0, hashing);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // link two polygon vertices with a bridge, duplicating the endpoints
    fn split_polygon(&mut self, a: u32, b: u32) -> u32 {
        let a2 = self.duplicate_node(a);
        let b2 = self.duplicate_node(b);

        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    fn is_valid_diagonal(&self, a: u32, b: u32) -> bool {
        let an = self.nodes[a].next;
        let ap = self.nodes[a].prev;
        let bn = self.nodes[b].next;
        let bp = self.nodes[b].prev;

        self.nodes[an].i != self.nodes[b].i
            && self.nodes[ap].i != self.nodes[b].i
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b) // locally visible
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0)) // no opposite-facing sectors
                || (self.nodes_eq(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0)) // special zero-length case
    }

    // signed area of triangle (a, b, c) — Mapbox predicate
    fn area(&self, a: u32, b: u32, c: u32) -> f64 {
        let pa = &self.nodes[a];
        let pb = &self.nodes[b];
        let pc = &self.nodes[c];
        (pb.y - pa.y) * (pc.x - pb.x) - (pb.x - pa.x) * (pc.y - pb.y)
    }

    fn nodes_eq(&self, p1: u32, p2: u32) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    // check if the polygon vertex a is locally inside relative to diagonal (a, b)
    fn locally_inside(&self, a: u32, b: u32) -> bool {
        let ap = self.nodes[a].prev;
        let an = self.nodes[a].next;
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    // check if the middle point of diagonal (a, b) is inside the polygon
    fn middle_inside(&self, a: u32, b: u32) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            let (px1, py1) = (self.nodes[p].x, self.nodes[p].y);
            let (px2, py2) = (self.nodes[pn].x, self.nodes[pn].y);
            if ((py1 > py) != (py2 > py))
                && py2 != py1
                && (px < (px2 - px1) * (py - py1) / (py2 - py1) + px1)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    // check if diagonal (a, b) intersects any polygon edge
    fn intersects_polygon(&self, a: u32, b: u32) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    // check if segment (p1, q1) intersects segment (p2, q2)
    fn intersects(&self, p1: u32, q1: u32, p2: u32, q2: u32) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true; // p1, q1 and p2 are colinear and p2 lies on p1q1
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true; // p1, q1 and q2 are colinear and q2 lies on p1q1
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true; // p2, q2 and p1 are colinear and p1 lies on p2q2
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true; // p2, q2 and q1 are colinear and q1 lies on p2q2
        }
        false
    }

    // for colinear points p, q, r: check if q lies on segment pr
    fn on_segment(&self, p: u32, q: u32, r: u32) -> bool {
        let (px, py) = (self.nodes[p].x, self.nodes[p].y);
        let (qx, qy) = (self.nodes[q].x, self.nodes[q].y);
        let (rx, ry) = (self.nodes[r].x, self.nodes[r].y);
        qx <= px.max(rx) && qx >= px.min(rx) && qy <= py.max(ry) && qy >= py.min(ry)
    }

    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<u32>) -> u32 {
        let id = self.nodes.0.len() as u32;
        let (prev, next) = match last {
            None => (id, id),
            Some(l) => (l, self.nodes[l].next),
        };
        self.nodes.0.push(Node {
            i,
            x,
            y,
            prev,
            next,
            z: 0,
            prev_z: NULL,
            next_z: NULL,
            steiner: false,
        });
        if let Some(l) = last {
            let ln = self.nodes[l].next;
            self.nodes[ln].prev = id;
            self.nodes[l].next = id;
        }
        id
    }

    fn duplicate_node(&mut self, src: u32) -> u32 {
        let id = self.nodes.0.len() as u32;
        self.nodes.0.push(Node {
            i: self.nodes[src].i,
            x: self.nodes[src].x,
            y: self.nodes[src].y,
            prev: NULL,
            next: NULL,
            z: 0,
            prev_z: NULL,
            next_z: NULL,
            steiner: false,
        });
        id
    }

    // unlink a node from both the polygon ring and the z-order list
    fn remove_node(&mut self, node: u32) {
        let next = self.nodes[node].next;
        let prev = self.nodes[node].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let pz = self.nodes[node].prev_z;
        let nz = self.nodes[node].next_z;
        if pz != NULL {
            self.nodes[pz].next_z = nz;
        }
        if nz != NULL {
            self.nodes[nz].prev_z = pz;
        }
    }

    // compute z-order of all nodes and build a sorted z-list
    fn index_curve(&mut self, start: u32, min_x: f64, min_y: f64, inv_size: f64) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = z_order(x, y, min_x, min_y, inv_size);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let pz = self.nodes[p].prev_z;
        self.nodes[pz].next_z = NULL;
        self.nodes[p].prev_z = NULL;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort, stable by z (ties keep list order)
    fn sort_linked(&mut self, head: u32) {
        let mut head = head;
        let mut in_size: usize = 1;
        loop {
            let mut p = head;
            head = NULL;
            let mut tail = NULL;
            let mut num_merges = 0usize;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0usize;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                }
                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size != 0
                        && (q_size == 0 || q == NULL || self.nodes[p].z <= self.nodes[q].z)
                    {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        head = e;
                    }
                    self.nodes[e].prev_z = tail;
                    tail = e;
                }
                p = q;
            }

            self.nodes[tail].next_z = NULL;
            in_size *= 2;
            if num_merges <= 1 {
                break;
            }
        }
    }
}

// inclusive point-in-triangle test
#[allow(clippy::too_many_arguments)]
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) >= (ax - px) * (cy - py)
        && (ax - px) * (by - py) >= (bx - px) * (ay - py)
        && (bx - px) * (cy - py) >= (cx - px) * (by - py)
}

fn sign(num: f64) -> i32 {
    if num > 0.0 {
        1
    } else if num < 0.0 {
        -1
    } else {
        0
    }
}

// 15-bit Morton code of coordinates normalized to [0, 32767]
fn z_order(x: f64, y: f64, min_x: f64, min_y: f64, inv_size: f64) -> i32 {
    // coords are transformed into non-negative 15-bit integer range
    let mut x = ((x - min_x) * inv_size) as i32;
    let mut y = ((y - min_y) * inv_size) as i32;

    x = (x | (x << 8)) & 0x00FF00FF;
    x = (x | (x << 4)) & 0x0F0F0F0F;
    x = (x | (x << 2)) & 0x33333333;
    x = (x | (x << 1)) & 0x55555555;

    y = (y | (y << 8)) & 0x00FF00FF;
    y = (y | (y << 4)) & 0x0F0F0F0F;
    y = (y | (y << 2)) & 0x33333333;
    y = (y | (y << 1)) & 0x55555555;

    x | (y << 1)
}

