1	//! Deterministic Mapbox-earcut-style ear clipping triangulation (std-only port).
2	//!
3	//! Single outer ring, no holes. Nodes live in a `Vec` and are referenced by
4	//! `u32` indices (no Rc/RefCell). Follows earcut.js / earcut.hpp semantics:
5	//! z-order hashing kicks in when the flattened coordinate count exceeds 160.
6	
7	use std::ops::{Index, IndexMut};
8	
9	const NULL: u32 = u32::MAX;
10	
11	struct Node {
12	    i: u32, // original vertex index
13	    x: f64,
14	    y: f64,
15	    prev: u32,
16	    next: u32,
17	    z: i32, // 15-bit Morton code (0 until computed)
18	    prev_z: u32,
19	    next_z: u32,
20	    steiner: bool,
21	}
22	
23	// node arena indexed by u32 node ids
24	struct Pool(Vec<Node>);
25	
26	impl Index<u32> for Pool {
27	    type Output = Node;
28	    fn index(&self, id: u32) -> &Node {
29	        &self.0[id as usize]
30	    }
31	}
32	
33	impl IndexMut<u32> for Pool {
34	    fn index_mut(&mut self, id: u32) -> &mut Node {
35	        &mut self.0[id as usize]
36	    }
37	}
38	
39	pub fn earcut(points: &[[f64; 2]]) -> Vec<u32> {
40	    let m = points.len();
41	    let mut triangles: Vec<u32> = Vec::new();
42	    if m == 0 {
43	        return triangles;
44	    }
45	
46	    // Enable z-order hashing when flattened coordinate count > 160 (m > 80).
47	    let (hashing, min_x, min_y, inv_size) = if m * 2 > 160 {
48	        let mut min_x = points[0][0];
49	        let mut max_x = points[0][0];
50	        let mut min_y = points[0][1];
51	        let mut max_y = points[0][1];
52	        for p in &points[1..] {
53	            min_x = min_x.min(p[0]);
54	            max_x = max_x.max(p[0]);
55	            min_y = min_y.min(p[1]);
56	            max_y = max_y.max(p[1]);
57	        }
58	        let mut inv = (max_x - min_x).max(max_y - min_y);
59	        inv = if inv != 0.0 { 32767.0 / inv } else { 0.0 };
60	        (true, min_x, min_y, inv)
61	    } else {
62	        (false, 0.0, 0.0, 0.0)
63	    };
64	
65	    let mut e = Earcut {
66	        nodes: Pool(Vec::with_capacity(m)),
67	    };
68	    if let Some(outer) = e.linked_list(points, true) {
69	        if e.nodes[outer].prev == e.nodes[outer].next {
70	            return triangles;
71	        }
72	        e.earcut_linked(outer, &mut triangles, min_x, min_y, inv_size, 0, hashing);
73	    }
74	    triangles
75	}
76	
77	struct Earcut {
78	    nodes: Pool,
79	}
80	
81	impl Earcut {
82	    // signed area of the ring: sum((x[j]-x[i])*(y[i]+y[j])), j = previous index
83	    fn signed_area(points: &[[f64; 2]]) -> f64 {
84	        let m = points.len();
85	        let mut sum = 0.0f64;
86	        let mut j = m - 1;
87	        for i in 0..m {
88	            sum += (points[j][0] - points[i][0]) * (points[i][1] + points[j][1]);
89	            j = i;
90	        }
91	        sum
92	    }
93	
94	    // create a circular doubly linked list from the ring in source order when
95	    // clockwise == (signed area > 0), otherwise in reverse order
96	    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> Option<u32> {
97	        let m = points.len();
98	        if m == 0 {
99	            return None;
100	        }
101	        let mut last: Option<u32> = None;
102	        if clockwise == (Self::signed_area(points) > 0.0) {
103	            for i in 0..m {
104	                last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
105	            }
106	        } else {
107	            for i in (0..m).rev() {
108	                last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
109	            }
110	        }
111	        let mut last = last?;
112	        if self.nodes_eq(last, self.nodes[last].next) {
113	            self.remove_node(last);
114	            last = self.nodes[last].next;
115	        }
116	        Some(last)
117	    }
118	
119	    // main loop: slice off ears one by one
120	    #[allow(clippy::too_many_arguments)]
121	    #[allow(unused_assignments)] // final ear/pass assignments mirror the JS reference structure
122	    fn earcut_linked(
123	        &mut self,
124	        ear: u32,
125	        triangles: &mut Vec<u32>,
126	        min_x: f64,
127	        min_y: f64,
128	        inv_size: f64,
129	        pass: u8,
130	        hashing: bool,
131	    ) {
132	        // interlink polygon nodes in z-order on the first (outer) pass
133	        if pass == 0 && inv_size != 0.0 {
134	            self.index_curve(ear, min_x, min_y, inv_size);
135	        }
136	
137	        let mut ear = ear;
138	        let mut stop = ear;
139	        let mut pass = pass;
140	
141	        while self.nodes[ear].prev != self.nodes[ear].next {
142	            let prev = self.nodes[ear].prev;
143	            let next = self.nodes[ear].next;
144	
145	            let is_ear = if hashing {
146	                self.is_ear_hashed(ear, min_x, min_y, inv_size)
147	            } else {
148	                self.is_ear(ear)
149	            };
150	
151	            if is_ear {
152	                triangles.push(self.nodes[prev].i);
153	                triangles.push(self.nodes[ear].i);
154	                triangles.push(self.nodes[next].i);
155	
156	                self.remove_node(ear);
157	
158	                // skipping the next vertex leads to less sliver triangles
159	                ear = self.nodes[next].next;
160	                stop = ear;
161	                continue;
162	            }
163	
164	            ear = next;
165	
166	            // looped through the whole remaining polygon without finding an ear
167	            if ear == stop {
168	                if pass == 0 {
169	                    // try filtering points and slicing again
170	                    ear = self.filter_points(ear, None);
171	                    pass = 1;
172	                } else if pass == 1 {
173	                    // try curing all small self-intersections locally
174	                    let filtered = self.filter_points(ear, None);
175	                    ear = self.cure_local_intersections(filtered, triangles);
176	                    pass = 2;
177	                } else if pass == 2 {
178	                    // last resort: split the remaining polygon in two
179	                    self.split_earcut(ear, triangles, min_x, min_y, inv_size, hashing);
180	                }
181	                break;
182	            }
183	        }
184	    }
