309	    // eliminate colinear or duplicate points; returns the new end node
310	    fn filter_points(&mut self, start: u32, end: Option<u32>) -> u32 {
311	        let mut end = end.unwrap_or(start);
312	        let mut p = start;
313	        loop {
314	            let mut again = false;
315	
316	            let pn = self.nodes[p].next;
317	            let pp = self.nodes[p].prev;
318	            if !self.nodes[p].steiner && (self.nodes_eq(p, pn) || self.area(pp, p, pn) == 0.0) {
319	                self.remove_node(p);
320	                p = self.nodes[p].prev;
321	                end = p;
322	
323	                if p == self.nodes[p].next {
324	                    break;
325	                }
326	                again = true;
327	            } else {
328	                p = self.nodes[p].next;
329	            }
330	
331	            if !(again || p != end) {
332	                break;
333	            }
334	        }
335	        end
336	    }
337	
338	    // walk the ring and try to cure small local self-intersections
339	    fn cure_local_intersections(&mut self, start: u32, triangles: &mut Vec<u32>) -> u32 {
340	        let mut start = start;
341	        let mut p = start;
342	        loop {
343	            let a = self.nodes[p].prev;
344	            let pn = self.nodes[p].next;
345	            let b = self.nodes[pn].next;
346	
347	            if !self.nodes_eq(a, b)
348	                && self.intersects(a, p, pn, b)
349	                && self.locally_inside(a, b)
350	                && self.locally_inside(b, a)
351	            {
352	                triangles.push(self.nodes[a].i);
353	                triangles.push(self.nodes[p].i);
354	                triangles.push(self.nodes[b].i);
355	
356	                self.remove_node(p);
357	                let pn = self.nodes[p].next;
358	                self.remove_node(pn);
359	
360	                p = b;
361	                start = b;
362	            }
363	            p = self.nodes[p].next;
364	            if p == start {
365	                break;
366	            }
367	        }
368	        self.filter_points(p, None)
369	    }
370	
371	    // try to find a valid diagonal and split the remaining polygon in two
372	    fn split_earcut(
373	        &mut self,
374	        start: u32,
375	        triangles: &mut Vec<u32>,
376	        min_x: f64,
377	        min_y: f64,
378	        inv_size: f64,
379	        hashing: bool,
380	    ) {
381	        let mut a = start;
382	        loop {
383	            let mut b = self.nodes[self.nodes[a].next].next;
384	            while b != self.nodes[a].prev {
385	                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
386	                    // split the polygon in two by the diagonal
387	                    let c = self.split_polygon(a, b);
388	
389	                    // filter colinear points around the cuts
390	                    let a_next = self.nodes[a].next;
391	                    let a2 = self.filter_points(a, Some(a_next));
392	                    let c_next = self.nodes[c].next;
393	                    let c2 = self.filter_points(c, Some(c_next));
394	
395	                    // run earcut on each half
396	                    self.earcut_linked(a2, triangles, min_x, min_y, inv_size, 0, hashing);
397	                    self.earcut_linked(c2, triangles, min_x, min_y, inv_size, 0, hashing);
398	                    return;
399	                }
400	                b = self.nodes[b].next;
401	            }
402	            a = self.nodes[a].next;
403	            if a == start {
404	                break;
405	            }
406	        }
407	    }
