409	    // link two polygon vertices with a bridge, duplicating the endpoints
410	    fn split_polygon(&mut self, a: u32, b: u32) -> u32 {
411	        let a2 = self.duplicate_node(a);
412	        let b2 = self.duplicate_node(b);
413	
414	        let an = self.nodes[a].next;
415	        let bp = self.nodes[b].prev;
416	
417	        self.nodes[a].next = b;
418	        self.nodes[b].prev = a;
419	
420	        self.nodes[a2].next = an;
421	        self.nodes[an].prev = a2;
422	
423	        self.nodes[b2].next = a2;
424	        self.nodes[a2].prev = b2;
425	
426	        self.nodes[bp].next = b2;
427	        self.nodes[b2].prev = bp;
428	
429	        b2
430	    }
431	
432	    fn is_valid_diagonal(&self, a: u32, b: u32) -> bool {
433	        let an = self.nodes[a].next;
434	        let ap = self.nodes[a].prev;
435	        let bn = self.nodes[b].next;
436	        let bp = self.nodes[b].prev;
437	
438	        self.nodes[an].i != self.nodes[b].i
439	            && self.nodes[ap].i != self.nodes[b].i
440	            && !self.intersects_polygon(a, b) // doesn't intersect other edges
441	            && ((self.locally_inside(a, b)
442	                && self.locally_inside(b, a)
443	                && self.middle_inside(a, b) // locally visible
444	                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0)) // no opposite-facing sectors
445	                || (self.nodes_eq(a, b)
446	                    && self.area(ap, a, an) > 0.0
447	                    && self.area(bp, b, bn) > 0.0)) // special zero-length case
448	    }
449	
450	    // signed area of triangle (a, b, c) — Mapbox predicate
451	    fn area(&self, a: u32, b: u32, c: u32) -> f64 {
452	        let pa = &self.nodes[a];
453	        let pb = &self.nodes[b];
454	        let pc = &self.nodes[c];
455	        (pb.y - pa.y) * (pc.x - pb.x) - (pb.x - pa.x) * (pc.y - pb.y)
456	    }
457	
458	    fn nodes_eq(&self, p1: u32, p2: u32) -> bool {
459	        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
460	    }
461	
462	    // check if the polygon vertex a is locally inside relative to diagonal (a, b)
463	    fn locally_inside(&self, a: u32, b: u32) -> bool {
464	        let ap = self.nodes[a].prev;
465	        let an = self.nodes[a].next;
466	        if self.area(ap, a, an) < 0.0 {
467	            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
468	        } else {
469	            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
470	        }
471	    }
472	
473	    // check if the middle point of diagonal (a, b) is inside the polygon
474	    fn middle_inside(&self, a: u32, b: u32) -> bool {
475	        let mut p = a;
476	        let mut inside = false;
477	        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
478	        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
479	        loop {
480	            let pn = self.nodes[p].next;
481	            let (px1, py1) = (self.nodes[p].x, self.nodes[p].y);
482	            let (px2, py2) = (self.nodes[pn].x, self.nodes[pn].y);
483	            if ((py1 > py) != (py2 > py))
484	                && py2 != py1
485	                && (px < (px2 - px1) * (py - py1) / (py2 - py1) + px1)
486	            {
487	                inside = !inside;
488	            }
489	            p = pn;
490	            if p == a {
491	                break;
492	            }
493	        }
494	        inside
495	    }
496	
497	    // check if diagonal (a, b) intersects any polygon edge
498	    fn intersects_polygon(&self, a: u32, b: u32) -> bool {
499	        let mut p = a;
500	        loop {
501	            let pn = self.nodes[p].next;
502	            if self.nodes[p].i != self.nodes[a].i
503	                && self.nodes[pn].i != self.nodes[a].i
504	                && self.nodes[p].i != self.nodes[b].i
505	                && self.nodes[pn].i != self.nodes[b].i
506	                && self.intersects(p, pn, a, b)
507	            {
508	                return true;
509	            }
510	            p = pn;
511	            if p == a {
512	                break;
513	            }
514	        }
515	        false
516	    }
517	
518	    // check if segment (p1, q1) intersects segment (p2, q2)
519	    fn intersects(&self, p1: u32, q1: u32, p2: u32, q2: u32) -> bool {
520	        let o1 = sign(self.area(p1, q1, p2));
521	        let o2 = sign(self.area(p1, q1, q2));
522	        let o3 = sign(self.area(p2, q2, p1));
523	        let o4 = sign(self.area(p2, q2, q1));
524	
525	        if o1 != o2 && o3 != o4 {
526	            return true; // general case
527	        }
528	        if o1 == 0 && self.on_segment(p1, p2, q1) {
529	            return true; // p1, q1 and p2 are colinear and p2 lies on p1q1
530	        }
531	        if o2 == 0 && self.on_segment(p1, q2, q1) {
532	            return true; // p1, q1 and q2 are colinear and q2 lies on p1q1
533	        }
534	        if o3 == 0 && self.on_segment(p2, p1, q2) {
535	            return true; // p2, q2 and p1 are colinear and p1 lies on p2q2
536	        }
537	        if o4 == 0 && self.on_segment(p2, q1, q2) {
538	            return true; // p2, q2 and q1 are colinear and q1 lies on p2q2
539	        }
540	        false
541	    }
542	
543	    // for colinear points p, q, r: check if q lies on segment pr
544	    fn on_segment(&self, p: u32, q: u32, r: u32) -> bool {
545	        let (px, py) = (self.nodes[p].x, self.nodes[p].y);
546	        let (qx, qy) = (self.nodes[q].x, self.nodes[q].y);
547	        let (rx, ry) = (self.nodes[r].x, self.nodes[r].y);
548	        qx <= px.max(rx) && qx >= px.min(rx) && qy <= py.max(ry) && qy >= py.min(ry)
549	    }
550	
551	    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<u32>) -> u32 {
552	        let id = self.nodes.0.len() as u32;
553	        let (prev, next) = match last {
554	            None => (id, id),
555	            Some(l) => (l, self.nodes[l].next),
556	        };
557	        self.nodes.0.push(Node {
558	            i,
559	            x,
560	            y,
561	            prev,
562	            next,
563	            z: 0,
564	            prev_z: NULL,
565	            next_z: NULL,
566	            steiner: false,
567	        });
568	        if let Some(l) = last {
569	            let ln = self.nodes[l].next;
570	            self.nodes[ln].prev = id;
571	            self.nodes[l].next = id;
572	        }
573	        id
574	    }
575	
576	    fn duplicate_node(&mut self, src: u32) -> u32 {
577	        let id = self.nodes.0.len() as u32;
578	        self.nodes.0.push(Node {
579	            i: self.nodes[src].i,
580	            x: self.nodes[src].x,
581	            y: self.nodes[src].y,
582	            prev: NULL,
583	            next: NULL,
584	            z: 0,
585	            prev_z: NULL,
586	            next_z: NULL,
587	            steiner: false,
588	        });
589	        id
590	    }
