592	    // unlink a node from both the polygon ring and the z-order list
593	    fn remove_node(&mut self, node: u32) {
594	        let next = self.nodes[node].next;
595	        let prev = self.nodes[node].prev;
596	        self.nodes[next].prev = prev;
597	        self.nodes[prev].next = next;
598	
599	        let pz = self.nodes[node].prev_z;
600	        let nz = self.nodes[node].next_z;
601	        if pz != NULL {
602	            self.nodes[pz].next_z = nz;
603	        }
604	        if nz != NULL {
605	            self.nodes[nz].prev_z = pz;
606	        }
607	    }
608	
609	    // compute z-order of all nodes and build a sorted z-list
610	    fn index_curve(&mut self, start: u32, min_x: f64, min_y: f64, inv_size: f64) {
611	        let mut p = start;
612	        loop {
613	            if self.nodes[p].z == 0 {
614	                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
615	                self.nodes[p].z = z_order(x, y, min_x, min_y, inv_size);
616	            }
617	            self.nodes[p].prev_z = self.nodes[p].prev;
618	            self.nodes[p].next_z = self.nodes[p].next;
619	            p = self.nodes[p].next;
620	            if p == start {
621	                break;
622	            }
623	        }
624	
625	        let pz = self.nodes[p].prev_z;
626	        self.nodes[pz].next_z = NULL;
627	        self.nodes[p].prev_z = NULL;
628	
629	        self.sort_linked(p);
630	    }
631	
632	    // Simon Tatham's linked list merge sort, stable by z (ties keep list order)
633	    fn sort_linked(&mut self, head: u32) {
634	        let mut head = head;
635	        let mut in_size: usize = 1;
636	        loop {
637	            let mut p = head;
638	            head = NULL;
639	            let mut tail = NULL;
640	            let mut num_merges = 0usize;
641	
642	            while p != NULL {
643	                num_merges += 1;
644	                let mut q = p;
645	                let mut p_size = 0usize;
646	                for _ in 0..in_size {
647	                    p_size += 1;
648	                    q = self.nodes[q].next_z;
649	                    if q == NULL {
650	                        break;
651	                    }
652	                }
653	                let mut q_size = in_size;
654	
655	                while p_size > 0 || (q_size > 0 && q != NULL) {
656	                    let e;
657	                    if p_size != 0
658	                        && (q_size == 0 || q == NULL || self.nodes[p].z <= self.nodes[q].z)
659	                    {
660	                        e = p;
661	                        p = self.nodes[p].next_z;
662	                        p_size -= 1;
663	                    } else {
664	                        e = q;
665	                        q = self.nodes[q].next_z;
666	                        q_size -= 1;
667	                    }
668	
669	                    if tail != NULL {
670	                        self.nodes[tail].next_z = e;
671	                    } else {
672	                        head = e;
673	                    }
674	                    self.nodes[e].prev_z = tail;
675	                    tail = e;
676	                }
