24	fn atoi(s: &str) -> i32 {
25	    let bytes = s.as_bytes();
26	    let mut i = 0;
27	
28	    // glibc isspace(): space, \t, \n, \v, \f, \r
29	    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
30	        i += 1;
31	    }
32	
33	    let mut negative = false;
34	    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
35	        negative = bytes[i] == b'-';
36	        i += 1;
37	    }
38	
39	    // Accumulate like strtol with long saturation (LONG_MAX / LONG_MIN).
40	    let mut value: i64 = 0;
41	    let mut overflowed = false;
42	    while i < bytes.len() && bytes[i].is_ascii_digit() {
43	        if !overflowed {
44	            let digit = (bytes[i] - b'0') as i64;
45	            match value
46	                .checked_mul(10)
47	                .and_then(|v| v.checked_add(digit))
48	            {
49	                Some(v) => value = v,
50	                None => overflowed = true,
51	            }
52	        }
53	        i += 1;
54	    }
55	
56	    if overflowed {
57	        value = i64::MAX;
58	    }
59	
60	    let result: i64 = if negative {
61	        if overflowed {
62	            // strtol returns LONG_MIN on negative overflow.
63	            i64::MIN
64	        } else {
65	            -value
66	        }
67	    } else {
68	        value
69	    };
